import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Double-submit contact form to detect duplicate submissions', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Name', 'Jane Doe')
  await opFill(page, 'Email', 'jane@example.com')
  await opFill(page, 'Message', 'Testing form submission behavior')
  await opClick(page, 'button', 'Send message')
  await opClick(page, 'button', 'Send message')
  await opSeen(page, 'dialog', 'Form submission error or success confirmation')
})
